scr.script:
			/*
variable ddlStatementsList should be used to return the list with DDL statements
that are created by script - as shown below:
ddlStatementsList.add(new java.lang.String(ddl));
other available variables:
- model - relational model instance
- pModel - physical model instance
- table - the table in relational model
- tableProxy - table definition in physical model
*/
var ddl;
var lname;
//journal table name suffix
jnTabSuf = "_JN";
// trigger name suffix
jnTrgSuf = "_JNtrg";
prompt = model.getAppView().getSettings().isIncludePromptInDDL();
useSchema = model.getAppView().getSettings().isIncludeSchemaInDDL();
if(model.getStorageDesign().isOpen()){
	if(useSchema){
	     lname = tableProxy.getLongName();
	}else{
		lname = tableProxy.getName();
	}
}else{
	if(useSchema){
	     lname = table.getLongName();
	}else{
		lname = table.getName();
	}
}
if(prompt){
	ddl= "PROMPT Creating Journal Table for '"+lname+"';\n";
}else{
	ddl = "";
}
ddl = ddl + "CREATE TABLE "+lname+jnTabSuf+"\n"+
" (JN_OPERATION CHAR(3) NOT NULL"+"\n"+
" ,JN_ORACLE_USER VARCHAR2(30) NOT NULL"+"\n"+
" ,JN_DATETIME DATE NOT NULL"+"\n"+
" ,JN_NOTES VARCHAR2(240)"+"\n"+
" ,JN_APPLN VARCHAR2(35)"+"\n"+
" ,JN_SESSION NUMBER(38)"+"\n";
cols = table.getElements();
for(var i=0;i<cols.length;i++){
	col = cols[i];
	ddl = ddl +" ,"+col.getName()+" "+col.getDatatypeString();
	if(col.isMandatory()){
		ddl = ddl + " NOT NULL\n";
	}else{
		ddl = ddl + "\n";
	}
}
ddl = ddl + " );";
ddlStatementsList.add(new java.lang.String(ddl));
if(prompt){
	ddl= "\nPROMPT Creating Journal Trigger for '"+lname+"';\n";
}else{
	ddl = "\n";
}
ddl = ddl +
"CREATE OR REPLACE TRIGGER "+lname+jnTrgSuf +"\n"+
"  AFTER \n" +
"  INSERT OR \n" +
"  UPDATE OR \n" +
"  DELETE ON "+lname+" for each row \n" +
" Declare \n" +
"  rec "+lname+"_JN"+"%ROWTYPE; \n" +
"  blank "+lname+"_JN"+"%ROWTYPE; \n" +
"  BEGIN \n" +
"    rec := blank; \n" +
"    IF INSERTING OR UPDATING THEN \n" ;
for(var i=0;i<cols.length;i++){
	col = cols[i];
	ddl = ddl + "      rec."+col.getName()+" := :NEW."+col.getName()+"; \n";
}
ddl = ddl +
"      rec.JN_DATETIME := SYSDATE; \n" +
"      rec.JN_ORACLE_USER := SYS_CONTEXT ('USERENV', 'SESSION_USER'); \n" +
"      rec.JN_APPLN := SYS_CONTEXT ('USERENV', 'MODULE'); \n" +
"      rec.JN_SESSION := SYS_CONTEXT ('USERENV', 'SESSIONID'); \n" +
"      IF INSERTING THEN \n" +
"        rec.JN_OPERATION := 'INS'; \n" +
"      ELSIF UPDATING THEN \n" +
"        rec.JN_OPERATION := 'UPD'; \n" +
"      END IF; \n" +
"    ELSIF DELETING THEN \n" ;
for(var i=0;i<cols.length;i++){
	col = cols[i];
	ddl = ddl + "      rec."+col.getName()+" := :OLD."+col.getName()+"; \n";
}
ddl = ddl +
"      rec.JN_DATETIME := SYSDATE; \n" +
"      rec.JN_ORACLE_USER := SYS_CONTEXT ('USERENV', 'SESSION_USER'); \n" +
"      rec.JN_APPLN := SYS_CONTEXT ('USERENV', 'MODULE'); \n" +
"      rec.JN_SESSION := SYS_CONTEXT ('USERENV', 'SESSIONID'); \n" +
"      rec.JN_OPERATION := 'DEL'; \n" +
"    END IF; \n" +
"    INSERT into "+lname+"_JN"+" VALUES rec; \n" +
"  END; \n" +
"  /"
ddlStatementsList.add(new java.lang.String(ddl));

			var index;
// define function - function parameter doesn't need to be named index
function checkFKColumns(index){
  //check it's foreign key index, otherwise FK is null
 if(index.isFK()){
 	if(!index.getFKAssociation().isMandatory()){
	 cols = index.getElements();
	 for(var i=0;i<cols.length;i++){
		if(cols[i].isMandatory()){
			return false;
		}
	 }
 	}
 }
 return true;
}
// invoke the function
checkFKColumns(index);

			tables = model.getTableSet().toArray();
for (var t = 0; t<tables.length;t++){
 table = tables[t];
 name = table.getName().toLowerCase();
 table.setName(name);
 columns = table.getElements();
 size = table.getElementsCollection().size();
 for (var i = 0; i < size; i++) {
	column = columns[i];
	cname = column.getName().toLowerCase();
	column.setName(cname);
 }
 table.setDirty(true);
 keys = table.getKeys();
 for (var i = 0; i < keys.length; i++) {
  key = keys[i];
    if(!key.isFK()){
     kname = key.getName().toLowerCase();
     key.setName(kname);
   }else{
     kname = key.getFKAssociation().getName().toLowerCase();
     key.getFKAssociation().setName(kname);
     key.getFKAssociation().setDirty(true);
   }
 }
}

			tables = model.getTableSet().toArray();
for (var t = 0; t<tables.length;t++){
 table = tables[t];
 abbr = table.getAbbreviation()+"_";
 if(!"_".equals(abbr)){
     columns = table.getElements();
     for (var i = 0; i < columns.length; i++) {
        column = columns[i];
        cname = column.getName();
        if(!cname.startsWith(abbr)){
         column.setName(abbr+cname);
        }
     }
 }
}

			tables = model.getTableSet().toArray();
for (var t = 0; t<tables.length;t++){
 table = tables[t];
 abbr = table.getAbbreviation()+"_";
 count = table.getAbbreviation().length()+1;
 if(!"_".equals(abbr)){
     columns = table.getElements();
     for (var i = 0; i < columns.length; i++) {
        column = columns[i];
        cname = column.getName();
        if(cname.startsWith(abbr)){
         column.setName(cname.substring(count));
         table.setDirty(true);
        }
     }
 }
}

			tables = model.getTableSet().toArray();
for (var t = 0; t<tables.length;t++){
 table = tables[t];
 name = table.getName().toUpperCase();
 table.setName(name);
 columns = table.getElements();
 size = table.getElementsCollection().size();
 for (var i = 0; i < size; i++) {
	column = columns[i];
	cname = column.getName().toUpperCase();
	column.setName(cname);
 }
 table.setDirty(true);
 keys = table.getKeys();
 for (var i = 0; i < keys.length; i++) {
  key = keys[i];
    if(!key.isFK()){
     kname = key.getName().toUpperCase();
     key.setName(kname);
   }else{
     kname = key.getFKAssociation().getName().toUpperCase();
     key.getFKAssociation().setName(kname);
     key.getFKAssociation().setDirty(true);
   }
 }
}

			// columns are found by column name
// allowing reuse of already existing columns
// dynamic property ctemplateID is set afterwards - will keep connection to template
// column even if the name of column is changed
var t_name = "table_template";
var p_name = "ctemplateID";
template = model.getTableSet().getByName(t_name);
if(template!=null){
    tcolumns = template.getElements();
    tables = model.getTableSet().toArray();
    for (var t = 0; t<tables.length;t++){
     table = tables[t];
    // compare name ignoring the case
     if(!table.getName().equalsIgnoreCase(t_name)){
         for (var i = 0; i < tcolumns.length; i++) {
            column = tcolumns[i];
            col = table.getElementByName(column.getName());
            if(col==null){
             col = table.getColumnByProperty(p_name,column.getObjectID());
            }
            if(col==null){
             col = table.createColumn();
            }
            column.copy(col);
            //set property after copy otherwise it'll be cleared by copy
            col.setProperty(p_name,column.getObjectID());
            table.setDirty(true);
         }
     }
    }
}

			max_length = 4000;
function copyComments(object){
 if(object.getCommentInRDBMS().equals("")){
   if(!object.getComment().equals("")){
     if(object.getComment().length()>max_length){
       object.setCommentInRDBMS(object.getComment().substring(0, max_length));
     }else{
       object.setCommentInRDBMS(object.getComment());
     }
     object.setDirty(true);
   }
 }
}

tables = model.getTableSet().toArray();
for (var t = 0; t<tables.length;t++){
 table = tables[t]
 copyComments(table);
 columns = table.getElements();
 size = table.getElementsCollection().size();
 for (var i = 0; i < columns.length; i++) {
	column = columns[i];
	copyComments(column);
 }
 keys = table.getKeys();
 for (var i = 0; i < keys.length; i++) {
   key = keys[i];
   if(!key.isFK()){
     copyComments(key);
   }else{
     copyComments(key.getFKAssociation());
   }
 }
}

			function getIndex(tab,cols){
 keys = tab.getKeys();
 for (var i = 0; i < keys.length; i++) {
  index = keys[i];
  if(!(index.isPK() || index.isUnique()) && !index.isFK() && index.isIndexForColumns(cols)){
     return index
   }
 }
 return null;
}

tables = model.getTableSet().toArray();
for (var t = 0; t<tables.length;t++){
 table = tables[t];
 indexes = table.getKeys();
 for (var i = 0; i < indexes.length; i++) {
    index = indexes[i];
    if(index.isFK()){
     columns = index.getColumns();
     if(columns.length>0){
       newIndex = getIndex(table,columns);
       if(newIndex==null){
         newIndex = table.createIndex()
         table.setDirty(true);
         for (var k = 0; k < columns.length; k++){
           newIndex.add(columns[k]);
         }
       }
     }
   }
 }
}

			// sorts table columns as asked here https://forums.oracle.com/forums/thread.jspa?threadID=2508315&tstart=0
// "...first the pks columns, after them fk columns and after the not null columns"
function addPKcolumns(list,table){
	pk = table.getPK();
	if(pk!=null){
		pcols = pk.getColumns();
		for(var i = 0;i<pcols.length;i++){
			col = pcols[i];
			//in fact don't need this check, because PK columns are processed first
			if(!list.contains(col)){
				list.add(col);
			}
		}
	}
}

function addFKcolumns(list,fkeys){
	for(var k=0;k<fkeys.length;k++){
		fcols = fkeys[k].getColumns();
		for(var i = 0;i<fcols.length;i++){
		  col = fcols[i];
		  if(!list.contains(col)){
			list.add(col);
		  }
		}
	}
}
//adds mandatory or oprional columns to list depending on mand parameter
function addMandatoryOptColumns(list,cols, mand){
	for(var i = 0;i<cols.length;i++){
		col = cols[i];
		if(col.isMandatory() == mand && !list.contains(col)){
			list.add(col);
		}
	}
}

tables = model.getTableSet().toArray();
list = new java.util.ArrayList();
for (var t = 0; t<tables.length;t++){
	list.clear();
	table = tables[t];
	cols = table.getElements();
	// add PK columns to list
	addPKcolumns(list,table);
	// add FK columns to list
	addFKcolumns(list,table.getFKAssociations());
	//add mandatory columns
	addMandatoryOptColumns(list,cols,true);
	//add optional columns
	addMandatoryOptColumns(list,cols,false);
	//use list to reorder columns
	ord_cols = list.toArray();
	for(var n = 0;n<ord_cols.length;n++){
		table.moveToIndex(ord_cols[n],n);
	}
	//prevent reordering from enginnering, can be changed with UI
	table.setAllowColumnReorder(false);
	table.setDirty(true);
}

			objs = model.getLastSearchResult().toArray();
var dp;
var sv;
//create subview and add tables to it
for(var i = 0;i<objs.length;i++){
	obj = objs[i];
	// use "Entity" for entities and logical model
	if(obj.getObjectTypeName().equals("Table")){
		if(dp==null){
			dp = obj.getDesignPart();
			sv = dp.createDesignPartSubView();
			// uncomment next line if want to set name
		     //sv.setName("Name");
		     sv.getPlaceHolder().setVisible(true);
		}
		sv.addViewFor(obj);
	}
}
if(dp!=null){
 //add foreign keys if you want to
 for(var i = 0;i<objs.length;i++){
	obj = objs[i];
	// use "Entity" for entities and logical model
	if(obj.getObjectTypeName().equals("Table")){
		tv = obj.getFirstViewForDPV(sv);
		if(tv!=null){
			//for entities and logical model use 
			//tv.addTVRelations(); 
			tv.addTVFKRelations();
		}
	}
 }
 //add Arcs if you want to
 for(var i = 0;i<objs.length;i++){
	obj = objs[i];
	if(obj.getObjectTypeName().equals("Table")){
		tv = obj.getFirstViewForDPV(sv);
		if(tv!=null){
			tv.addArcs();
		}
	}
 }
 //arrange diagram
 sv.rearrangeNewDiagram();
}

			/* removes the columns created with "Table template..." script, also removes related attributes
*  from logical model
*  more details here http://www.thatjeffsmith.com/archive/2015/03/adding-common-columns-to-tables-via-templates-and-transformation-scripts/
*/
var t_name = "table_template";
var p_name = "ctemplateID";
template = model.getTableSet().getByName(t_name);
if(template!=null){
    tcolumns = template.getElements();
    tables = model.getTableSet().toArray();
    for (var t = 0; t<tables.length;t++){
     table = tables[t];
    // compare name ignoring the case
     if(!table.getName().equalsIgnoreCase(t_name)){
         for (var i = 0; i < tcolumns.length; i++) {
            column = tcolumns[i];
            col = table.getColumnByProperty(p_name,column.getObjectID());
            if(col!=null){
            	attr = col.getEngAttribute();
            	if(attr!=null){
            		ent = attr.getEntity();
            		attr.remove();
            		if(ent!=null){
            			ent.setDirty(true);
            		}
            	}
             col.remove();
             table.setDirty(true);
            }
         }
     }
    }
}

			tables = model.getTableSet().toArray();
for (var t = 0; t<tables.length;t++){
 table = tables[t];
 table.setName(table.getName().replace("-","_"));

     columns = table.getElements();
     for (var i = 0; i < columns.length; i++) {
        column = columns[i];
        column.setName(column.getName().replace("-","_"));
        column.setName(column.getName().replace("Ä","A"));
        column.setName(column.getName().replace("Ü","U"));
        column.setName(column.getName().replace("Ö","O"));
 }
}

			//scripts to handle translation of model
	var gLogNote = "LOG";
	var gCurrentLang = "DE";
	var gLanguages = "DE,EN";
	var gTranslInforegexp =/TRANSLATION\{[^}]*\}/;
	var logInitialized = false;
	var NOTESSTARTTAG = '[<tag>[\n';
	var NOTESENDTAG = '\n]<tag>]';
	var PLAINMESSAGE = 1;
	var ERRORMESSAGE = 0;
	var WARNINGMESSAGE = 2;
	var QUESTIONMESSAGE = 3;
	var gLangArray = []; 
	var gCurVersion = '';
	var CODEVERSION = '1.0';


	function fullmessage(msg,type) {
		Java.type("javax.swing.JOptionPane").showMessageDialog(null
		, msg,'ODM-Translation', type);
	}

	function error(msg) {
		fullmessage(msg,ERRORMESSAGE);
		}
	function message(msg) {
		fullmessage(msg,PLAINMESSAGE);
		}

	function initLog(){
		if (! logInitialized){
			var lNote = model.getNoteSet().getByName(gLogNote);
	     	if (lNote == null) {
	    	    		lNote = model.createNote()
		    		lNote.setName(gLogNote);
	     	}
	     	lNote.setComment("");
	     	logInitialized = true;
		}
	}
	function log(plog){
		initLog();
		var lNote = model.getNoteSet().getByName(gLogNote);
	     lNote.setComment(lNote.getComment()+"\n"+plog);
	}

	function getTranslInfo(){
		var lDesignComment = model.design.getComment();
	     lmatchTransl= lDesignComment.match(gTranslInforegexp);
	     return lmatchTransl;    
	}

	function setTranslInfo(curLang,langs,version) {
		model.design.setComment(
			"TRANSLATION{\ncurrentLang="+curLang
			+"\nlanguages="+langs
			+"\nlastSync="
			+"\nversion="+version+"\n}\n"
			+ model.design.getComment());
	}
	function updTranslInfo(curLang,langs,version,datetime) {
		curComment = model.design.getComment();
		model.design.setComment(
			curComment.replace(gTranslInforegexp,
			"TRANSLATION{\ncurrentLang="+curLang
			+"\nlanguages="+langs
			+"\nlastSync="+datetime
			+"\nversion="+version+"\n}"
			));
	}

	function buildRegExpTag(innertag,tag){
		return tag.replace('<tag>',innertag).replace(/\[/g,'\\[').replace(/\]/g,'\\]')
	}

	function textFromNote(tag,obj) {
    	note = obj.getNotes()
    	restart =  buildRegExpTag(tag, NOTESSTARTTAG)
    	reend =  buildRegExpTag (tag, NOTESENDTAG)+"[\n]*"
    	re = new RegExp(restart + '([^]*)' + reend)
    	ma = note.match(re)
    	retval = ''
	   	if (ma != null) {
			//message("|"+reend+"|\n"+"|"+ma[0]+"|")
	   		retval = ma[1]
		}
		return retval
	}

	function textToNote(tag,obj,value) {
    	note = obj.getNotes()
    	restart =  buildRegExpTag(tag, NOTESSTARTTAG)
    	reend =  buildRegExpTag (tag, NOTESENDTAG)+"[\n]*"
    	re = new RegExp(restart + '([^]*)' + reend)
    	ma = note.match(re)
		newentry = NOTESSTARTTAG.replace('<tag>',tag) 
			+ value 
			+ NOTESENDTAG.replace('<tag>',tag)
			+'\n'
	   	if (ma == null) {
	   		note = note + newentry
		} else {
			//message("|"+newentry+"|\n"+"|"+ma[0]+"|")
			note = note.replace(ma[0] , newentry)
		}

		obj.setNotes(note)
	}

	function init(istUpgrade){
		lmatchTransl = getTranslInfo();
		if (lmatchTransl == null) {
			throw new Error("\n***TRANSLATION not installed***\n");
		}
		ltext= String(lmatchTransl).match(/currentLang=[A-Z]{2}/);
		lparts = String(ltext).split("=");
		//log("curLang="+lparts[1]);
	     gCurrentLang = lparts[1];

		ltext= String(lmatchTransl).match(/languages=[A-Z,]*/);
		lparts = String(ltext).split("=");
	     //log("languages="+lparts[1]);
	     gLanguages = lparts[1]
		gLangArray = gLanguages.split(',');

		ltext= String(lmatchTransl).match(/version=[0-9\.]*/);
		lparts = String(ltext).split("=");
		gCurVersion = lparts[1]
		if (gCurVersion != CODEVERSION && !istUpgrade) {
			msg = "\n***TRANSLATION version mismatch: "
				+"expected " + CODEVERSION + " found "+gCurVersion
				+"\nPlease upgrade.***\n"
			throw new Error(msg);
		}
	}

	function doLangValue(propName,obj,value,isNote,notNull){
		lpropName = gCurrentLang + propName;
	    oldval = (isNote) ? textFromNote(lpropName,obj) : obj.getProperty(lpropName);
		lprefix =  '*'+gCurrentLang+'* '
		//markiere oder fülle die fremden Properties
		for (il=0;il<gLangArray.length;il++) {
			// nur die fremden Sprachen ersetzen
			flang = gLangArray[il]
			if (flang != gCurrentLang) {
				fpropName = flang + propName;
				fprop = (isNote) ? textFromNote(fpropName,obj) : obj.getProperty(fpropName);
				// Falls die Fremdsprache noch automtaisch übersetzt ist ( *XX* vorneweg hat), überschreibe sie
				if (fprop.match(/^\*[A-Z]{2}\* /)) {
				   if (isNote) textToNote(fpropName,obj,lprefix+value);
					  else obj.setProperty(fpropName,lprefix+value);
				} else if (fprop.startsWith('*')) {
					// ** und * sind in Bearbeitung nichts ersetzen
				} else if (fprop == "" && value == "" && ! notNull) {
					// das Ziel ist leer, der neue Wert auch und es ist kein Mussfeld. lass das Ziel leer
				} else if (fprop == "") {
					// das Ziel ist leer aber aus einem Grund muss ich es überschreiben (siehe vorheriges IF)
				   if (isNote) textToNote(fpropName,obj,lprefix+value);
					  else obj.setProperty(fpropName,lprefix+value);
			    } else {
					// das Ziel ist gefüllt, nicht in Bearbeitung und nicht automatisch übersetzt.
					// d.h. es hat einen gültigen Wert. Markiere es, falls die Quelle wirklich geändert hat
					//**if (oldval == 'Entität 1') message("vor IF "+oldval)
					if ( ! (value == oldval 
						  || oldval.match(/^\*[A-Z]{2}\* /)
						  || oldval.startsWith("**")
						  || oldval.startsWith("*")) ) {
						  //**if (oldval == 'Entität 1') message("in IF "+oldval)
						  // die Quelle ist kein Feld, das in Bearbeitung oder autmoatisch übersetzt ist
						  if (isNote) textToNote(fpropName,obj,"*"+fprop);
					   		else obj.setProperty(fpropName,"*"+fprop)
					}
				}
			} 
		}
		// die Werte der CurrentLang kommen aus dem Objekt, überschreibe immer
		if (isNote) textToNote(lpropName,obj,value);
		   else obj.setProperty(lpropName, value);
	}

	function doProperty(propName,obj,value,notNull){
		doLangValue(propName,obj,value,false,notNull);
	}

	function doNote(tag,obj,value) {
		doLangValue(tag,obj,value,true,false);
	}

	function fuellUDP(){
		entities = model.getEntitySet().toArray();
		for (ie=0;ie<entities.length;ie++) { //
			ent = entities[ie];
			doProperty("_ENTI_NAME",ent,ent.getName(),true)
			doNote("_ENTI_COMMENT",ent,ent.getComment())
			doProperty("_ENTI_SYNONYM",ent,ent.getSynonym())

			attrs = ent.getAttributes().toArray();
			//log("Attrs="+attrs.length)
			for (ia=0;ia<attrs.length;ia++) { //
				attr = attrs[ia];
				for (il=0;il<gLangArray.length;il++) {
					doProperty("_ATTR_NAME",attr,attr.getName(),true);
					doNote("_ATTR_COMMENT",attr,attr.getComment());			
				}
			}
		ent.setDirty(true);
		}
		relationships = model.getRelationSet().toArray();
		for (ir=0;ir<relationships.length;ir++) { //
			rel = relationships[ir];
			sourcename = rel.getNameOnSource()
			targetname = rel.getNameOnTarget()
			//if (i > 0) throw new Error ("\n"+gLangArray[i]+"_RELA_TEXT_FROM"+"\n"+gLangArray.length);
			doProperty("_RELA_TEXT_FROM",rel,sourcename)
			doProperty("_RELA_TEXT_TO",rel,targetname)	
			rel.setDirty(true);
		}
	}

	function setProperties(lang){
		entities = model.getEntitySet().toArray();
		for (ie=0;ie<entities.length;ie++) { //
			ent = entities[ie];
			ent.setName(ent.getProperty(lang+"_ENTI_NAME"));
			ent.setComment(textFromNote(lang+"_ENTI_COMMENT",ent))
			ent.setSynonym(ent.getProperty(lang+"_ENTI_SYNONYM"));

			attrs = ent.getAttributes().toArray();
			//log("Attrs="+attrs.length)
			for (ia=0;ia<attrs.length;ia++) { //
				attr = attrs[ia];
				//log(attr.getName(),attr.getComment());
				attr.setName(attr.getProperty(lang+"_ATTR_NAME"));
				attr.setComment(textFromNote(lang+"_ATTR_COMMENT",attr))
			}		
			ent.setDirty(true);
		}
		relationships = model.getRelationSet().toArray();
		for (ir=0;ir<relationships.length;ir++) { 
			rel = relationships[ir];
			rel.setNameOnSource(rel.getProperty(lang+"_RELA_TEXT_FROM"));
			rel.setNameOnTarget(rel.getProperty(lang+"_RELA_TEXT_TO"));
			rel.setDirty(true);
		}
	}

	function curDateStr(){
		var currentdate = new Date();
		return  currentdate.getDate() 
		+ "/" + (currentdate.getMonth()+1) 
		+ "/" + currentdate.getFullYear() + "  " 
		+ currentdate.getHours() + ":" 
		+ currentdate.getMinutes() + ":" + currentdate.getSeconds();
	}

	function changeLang(pfromLang,ptoLang){
		//log("3:"+gLanguages);
	//	log("change from " + pfromLang + " to " + ptoLang);
		fuellUDP();
		setProperties(ptoLang);
		gCurrentLang = ptoLang;
		updTranslInfo(gCurrentLang, gLanguages
					,gCurVersion,curDateStr());	
		model.design.setDirty(true);
	}

	function initTranslation() {
		lmatchTransl= getTranslInfo()
		if (lmatchTransl == null) {
			setTranslInfo(gCurrentLang
			,gLanguages,CODEVERSION);		
		} else {
			lversion = String(lmatchTransl).match(/version=[0-9\.]*/);
			throw new Error("\n***TRANSLATION ("+lversion+") already installed***\n");
		}
		//hier gibt es einen Eintrag für die Translation
		init();
		// fülle die UDP für die Übersetzungen
		fuellUDP();
		updTranslInfo(gCurrentLang, gLanguages
					 ,gCurVersion,curDateStr());
		model.design.setDirty(true);
		message ("TRANLSATION installed current-language="+gCurrentLang
		         + " languages="+gLanguages+" version="+gCurVersion
			        ,PLAINMESSAGE);
	}

	function changeLanguage() {
		init();
		options = [];
		lcurlang = gCurrentLang
		for (il=0;il<gLangArray.length;il++) {
			if (gLangArray[il] != lcurlang) {
				options.push(gCurrentLang + '->' + gLangArray[il])
			}
		}
		if (options.length == 1) {
			antwort = options[0]
		} else {
			antwort = Java.type("javax.swing.JOptionPane").showInputDialog(null, 
	        	"Choose language change",
				"Change language",
				QUESTIONMESSAGE,
				null, 
				options, 
				options[0]);
		}
        if (antwort != null){
			toLang = antwort.substr(-2)
			//Java.type("javax.swing.JOptionPane").showMessageDialog(null, antwort+'|'+toLang);
			changeLang(gCurrentLang,toLang);
			message ("Model language changed from "+lcurlang+" to "+toLang
						+".\n Please hide and re-display labels."
			        ,PLAINMESSAGE);
		}
	}

	function upgrade09_to_10() {
		// move comments from properties to comments
		entities = model.getEntitySet().toArray();
		for (ie=0;ie<entities.length;ie++) { 
			ent = entities[ie];
			for (il=0;il<gLangArray.length;il++) {
				// nur die fremden Sprachen ersetzen
				lang = gLangArray[il];
				textToNote(lang+"_ENTI_COMMENT",ent,ent.getProperty(lang+"_ENTI_COMMENT"));

				attrs = ent.getAttributes().toArray();
				for (ia=0;ia<attrs.length;ia++) { //
					attr = attrs[ia];
					textToNote(lang+"_ATTR_COMMENT",attr,attr.getProperty(lang+"_ATTR_COMMENT"));
				}
			}
			ent.setDirty(true);
		}
	}

	function upgradeTranslation () {
		init(true);				
		//1.0 has no upgrades
		if (gCurVersion  == CODEVERSION) {
			message("TRANSLATE: latest version ("+gCurVersion+") is installed")
		} else {
			upgraded = false
			if (gCurVersion == "0.9") {
				upgrade09_to_10();
				gCurVersion = "1.0";
				upgraded = true
			}
			if (upgraded) {
				updTranslInfo(gCurrentLang, gLanguages
					 ,CODEVERSION,curDateStr());	
				message("TRANSLATE: latest version ("+CODEVERSION+") is now installed")
			} else {
			error("\nTRANSLATE: unknown version ("+gCurVersion+").\n"
					+"Please contact support\n");
			}
		}			
	}

			//scripts to handle translation of model
	var gLogNote = "LOG";
	var gCurrentLang = "DE";
	var gLanguages = "DE,EN";
	var gTranslInforegexp =/TRANSLATION\{[^}]*\}/;
	var logInitialized = false;
	var NOTESSTARTTAG = '[<tag>[\n';
	var NOTESENDTAG = '\n]<tag>]';
	var PLAINMESSAGE = 1;
	var ERRORMESSAGE = 0;
	var WARNINGMESSAGE = 2;
	var QUESTIONMESSAGE = 3;
	var gLangArray = []; 
	var gCurVersion = '';
	var CODEVERSION = '1.0';


	function fullmessage(msg,type) {
		Java.type("javax.swing.JOptionPane").showMessageDialog(null
		, msg,'ODM-Translation', type);
	}

	function error(msg) {
		fullmessage(msg,ERRORMESSAGE);
		}
	function message(msg) {
		fullmessage(msg,PLAINMESSAGE);
		}

	function initLog(){
		if (! logInitialized){
			var lNote = model.getNoteSet().getByName(gLogNote);
	     	if (lNote == null) {
	    	    		lNote = model.createNote()
		    		lNote.setName(gLogNote);
	     	}
	     	lNote.setComment("");
	     	logInitialized = true;
		}
	}
	function log(plog){
		initLog();
		var lNote = model.getNoteSet().getByName(gLogNote);
	     lNote.setComment(lNote.getComment()+"\n"+plog);
	}

	function getTranslInfo(){
		var lDesignComment = model.design.getComment();
	     lmatchTransl= lDesignComment.match(gTranslInforegexp);
	     return lmatchTransl;    
	}

	function setTranslInfo(curLang,langs,version) {
		model.design.setComment(
			"TRANSLATION{\ncurrentLang="+curLang
			+"\nlanguages="+langs
			+"\nlastSync="
			+"\nversion="+version+"\n}\n"
			+ model.design.getComment());
	}
	function updTranslInfo(curLang,langs,version,datetime) {
		curComment = model.design.getComment();
		model.design.setComment(
			curComment.replace(gTranslInforegexp,
			"TRANSLATION{\ncurrentLang="+curLang
			+"\nlanguages="+langs
			+"\nlastSync="+datetime
			+"\nversion="+version+"\n}"
			));
	}

	function buildRegExpTag(innertag,tag){
		return tag.replace('<tag>',innertag).replace(/\[/g,'\\[').replace(/\]/g,'\\]')
	}

	function textFromNote(tag,obj) {
    	note = obj.getNotes()
    	restart =  buildRegExpTag(tag, NOTESSTARTTAG)
    	reend =  buildRegExpTag (tag, NOTESENDTAG)+"[\n]*"
    	re = new RegExp(restart + '([^]*)' + reend)
    	ma = note.match(re)
    	retval = ''
	   	if (ma != null) {
			//message("|"+reend+"|\n"+"|"+ma[0]+"|")
	   		retval = ma[1]
		}
		return retval
	}

	function textToNote(tag,obj,value) {
    	note = obj.getNotes()
    	restart =  buildRegExpTag(tag, NOTESSTARTTAG)
    	reend =  buildRegExpTag (tag, NOTESENDTAG)+"[\n]*"
    	re = new RegExp(restart + '([^]*)' + reend)
    	ma = note.match(re)
		newentry = NOTESSTARTTAG.replace('<tag>',tag) 
			+ value 
			+ NOTESENDTAG.replace('<tag>',tag)
			+'\n'
	   	if (ma == null) {
	   		note = note + newentry
		} else {
			//message("|"+newentry+"|\n"+"|"+ma[0]+"|")
			note = note.replace(ma[0] , newentry)
		}

		obj.setNotes(note)
	}

	function init(istUpgrade){
		lmatchTransl = getTranslInfo();
		if (lmatchTransl == null) {
			throw new Error("\n***TRANSLATION not installed***\n");
		}
		ltext= String(lmatchTransl).match(/currentLang=[A-Z]{2}/);
		lparts = String(ltext).split("=");
		//log("curLang="+lparts[1]);
	     gCurrentLang = lparts[1];

		ltext= String(lmatchTransl).match(/languages=[A-Z,]*/);
		lparts = String(ltext).split("=");
	     //log("languages="+lparts[1]);
	     gLanguages = lparts[1]
		gLangArray = gLanguages.split(',');

		ltext= String(lmatchTransl).match(/version=[0-9\.]*/);
		lparts = String(ltext).split("=");
		gCurVersion = lparts[1]
		if (gCurVersion != CODEVERSION && !istUpgrade) {
			msg = "\n***TRANSLATION version mismatch: "
				+"expected " + CODEVERSION + " found "+gCurVersion
				+"\nPlease upgrade.***\n"
			throw new Error(msg);
		}
	}

	function doLangValue(propName,obj,value,isNote,notNull){
		lpropName = gCurrentLang + propName;
	    oldval = (isNote) ? textFromNote(lpropName,obj) : obj.getProperty(lpropName);
		lprefix =  '*'+gCurrentLang+'* '
		//markiere oder fülle die fremden Properties
		for (il=0;il<gLangArray.length;il++) {
			// nur die fremden Sprachen ersetzen
			flang = gLangArray[il]
			if (flang != gCurrentLang) {
				fpropName = flang + propName;
				fprop = (isNote) ? textFromNote(fpropName,obj) : obj.getProperty(fpropName);
				// Falls die Fremdsprache noch automtaisch übersetzt ist ( *XX* vorneweg hat), überschreibe sie
				if (fprop.match(/^\*[A-Z]{2}\* /)) {
				   if (isNote) textToNote(fpropName,obj,lprefix+value);
					  else obj.setProperty(fpropName,lprefix+value);
				} else if (fprop.startsWith('*')) {
					// ** und * sind in Bearbeitung nichts ersetzen
				} else if (fprop == "" && value == "" && ! notNull) {
					// das Ziel ist leer, der neue Wert auch und es ist kein Mussfeld. lass das Ziel leer
				} else if (fprop == "") {
					// das Ziel ist leer aber aus einem Grund muss ich es überschreiben (siehe vorheriges IF)
				   if (isNote) textToNote(fpropName,obj,lprefix+value);
					  else obj.setProperty(fpropName,lprefix+value);
			    } else {
					// das Ziel ist gefüllt, nicht in Bearbeitung und nicht automatisch übersetzt.
					// d.h. es hat einen gültigen Wert. Markiere es, falls die Quelle wirklich geändert hat
					//**if (oldval == 'Entität 1') message("vor IF "+oldval)
					if ( ! (value == oldval 
						  || oldval.match(/^\*[A-Z]{2}\* /)
						  || oldval.startsWith("**")
						  || oldval.startsWith("*")) ) {
						  //**if (oldval == 'Entität 1') message("in IF "+oldval)
						  // die Quelle ist kein Feld, das in Bearbeitung oder autmoatisch übersetzt ist
						  if (isNote) textToNote(fpropName,obj,"*"+fprop);
					   		else obj.setProperty(fpropName,"*"+fprop)
					}
				}
			} 
		}
		// die Werte der CurrentLang kommen aus dem Objekt, überschreibe immer
		if (isNote) textToNote(lpropName,obj,value);
		   else obj.setProperty(lpropName, value);
	}

	function doProperty(propName,obj,value,notNull){
		doLangValue(propName,obj,value,false,notNull);
	}

	function doNote(tag,obj,value) {
		doLangValue(tag,obj,value,true,false);
	}

	function fuellUDP(){
		entities = model.getEntitySet().toArray();
		for (ie=0;ie<entities.length;ie++) { //
			ent = entities[ie];
			doProperty("_ENTI_NAME",ent,ent.getName(),true)
			doNote("_ENTI_COMMENT",ent,ent.getComment())
			doProperty("_ENTI_SYNONYM",ent,ent.getSynonym())

			attrs = ent.getAttributes().toArray();
			//log("Attrs="+attrs.length)
			for (ia=0;ia<attrs.length;ia++) { //
				attr = attrs[ia];
				for (il=0;il<gLangArray.length;il++) {
					doProperty("_ATTR_NAME",attr,attr.getName(),true);
					doNote("_ATTR_COMMENT",attr,attr.getComment());			
				}
			}
		ent.setDirty(true);
		}
		relationships = model.getRelationSet().toArray();
		for (ir=0;ir<relationships.length;ir++) { //
			rel = relationships[ir];
			sourcename = rel.getNameOnSource()
			targetname = rel.getNameOnTarget()
			//if (i > 0) throw new Error ("\n"+gLangArray[i]+"_RELA_TEXT_FROM"+"\n"+gLangArray.length);
			doProperty("_RELA_TEXT_FROM",rel,sourcename)
			doProperty("_RELA_TEXT_TO",rel,targetname)	
			rel.setDirty(true);
		}
	}

	function setProperties(lang){
		entities = model.getEntitySet().toArray();
		for (ie=0;ie<entities.length;ie++) { //
			ent = entities[ie];
			ent.setName(ent.getProperty(lang+"_ENTI_NAME"));
			ent.setComment(textFromNote(lang+"_ENTI_COMMENT",ent))
			ent.setSynonym(ent.getProperty(lang+"_ENTI_SYNONYM"));

			attrs = ent.getAttributes().toArray();
			//log("Attrs="+attrs.length)
			for (ia=0;ia<attrs.length;ia++) { //
				attr = attrs[ia];
				//log(attr.getName(),attr.getComment());
				attr.setName(attr.getProperty(lang+"_ATTR_NAME"));
				attr.setComment(textFromNote(lang+"_ATTR_COMMENT",attr))
			}		
			ent.setDirty(true);
		}
		relationships = model.getRelationSet().toArray();
		for (ir=0;ir<relationships.length;ir++) { 
			rel = relationships[ir];
			rel.setNameOnSource(rel.getProperty(lang+"_RELA_TEXT_FROM"));
			rel.setNameOnTarget(rel.getProperty(lang+"_RELA_TEXT_TO"));
			rel.setDirty(true);
		}
	}

